import {art,fieldArt} from './art.js';
const app=document.querySelector('#app');
document.addEventListener('visibilitychange',()=>{document.documentElement.dataset.hidden=String(document.hidden);});
const icons={cube:'M12 2 3 7v10l9 5 9-5V7Zm0 0v10m-9-5 9 5 9-5m-9 5v10',arrow:'M5 12h14m-5-5 5 5-5 5',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',play:'m8 5 11 7-11 7Z',pause:'M8 5v14M16 5v14',orbit:'M12 3a9 9 0 1 0 9 9M3 8c3-5 19 3 18 8S2 18 3 8Zm9 1v6m-3-3h6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',layers:'m12 3-10 5 10 5 10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',back:'M19 12H5m5-5-5 5 5 5',reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',image:'M3 3h18v18H3Zm0 13 6-6 5 5 3-3 4 4M16 7h.01',save:'M4 3h14l3 3v15H3V3Zm3 0v7h10V3M7 21v-7h10v7',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',share:'M8 12l8-6m-8 6 8 6M7 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0M22 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0M22 20a3 3 0 1 1-6 0 3 3 0 0 1 6 0',step:'m5 5 11 7-11 7ZM19 5v14',x:'M4 3 20 21M20 3 4 21',youtube:'M3 6h18v12H3Zm7 3 5 3-5 3Z',instagram:'M7 3h10a4 4 0 0 1 4 4v10a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4V7a4 4 0 0 1 4-4ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0m1-5h.01',discord:'M5 6 2 18l6 3 1-3h6l1 3 6-3-3-12-5-2-1 2h-3L8 4Zm3 7h.01m8 0h.01'};
export const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.cube}"/></svg>`;
const brand=()=>`<a class="brand" href="${url('')}" aria-label="POLYVERSE home">${icon('cube')}<span><strong>POLYVERSE</strong><small>BEYOND DIMENSION</small></span></a>`;
let host,config,sceneId,isSimulator=false,activeRealm=0,intro=null,dialogReturn=null,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,filter='all',query='',walk=null,toastTimer;
try{paused=JSON.parse(sessionStorage.getItem('polyverse.paused')??String(paused));}catch{}
let decodedPath;try{decodedPath=decodeURI(location.pathname);}catch{decodedPath=location.pathname;}
const initialPath=decodedPath.replace(base,'').replace(/^\//,'').replace(/index\.html$/,'').replace(/\/+$/,'');
const route=initialPath;
function header(){return `<header class="site-header">${brand()}<nav class="desktop-nav" aria-label="Main navigation">${nav.map(([name,path])=>`<a href="${url(path)}" class="${route===path.replace(/\/$/,'')?'active':''}" ${route===path.replace(/\/$/,'')?'aria-current="page"':''}>${name}</a>`).join('')}</nav><div class="header-actions"><button class="icon-button" data-action="search" aria-label="Search models and worlds">${icon('search')}</button><a class="button primary compact" href="${url('simulator/')}">ENTER SIMULATION ${icon('arrow')}</a><button class="icon-button menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button></div><nav class="mobile-menu" hidden aria-label="Mobile navigation">${nav.map(([n,p])=>`<a href="${url(p)}">${n}</a>`).join('')}</nav></header>`;}
function footer(){return `<footer class="site-footer">${brand()}<nav class="footer-nav" aria-label="Footer">${nav.map(([n,p])=>`<a href="${url(p)}">${n}</a>`).join('')}</nav><div class="footer-right"><div class="social-links">${['x','youtube','instagram','discord'].map(n=>`<button class="icon-button" data-action="community" aria-label="${n} community information">${icon(n)}</button>`).join('')}</div><span class="footer-motto">GEOMETRY LIVES FOREVER.</span></div></footer><div class="bottom-strip"><span>© 2026 POLYVERSE · AN INTERACTIVE GEOMETRIC UNIVERSE</span><span>BUILT FROM MATHEMATICS. OPEN TO POSSIBILITY.</span><a class="icp-link" href="https://beian.miit.gov.cn/" target="_blank" rel="noopener noreferrer" lang="zh-CN">渝ICP备2026024419号-1</a></div>`;}
function home(){document.title='POLYVERSE — Beyond Dimension';app.innerHTML=header()+`<main><section class="hero" aria-labelledby="hero-title"><div class="hero-scene" id="home-scene"></div><div class="hero-copy"><p class="eyebrow">A UNIVERSE OF PURE GEOMETRY</p><h1 id="hero-title">MULTIDIMENSIONAL<span>GEOMETRY</span></h1><p class="hero-description">A limitless world governed only by geometric physical rules.<br>Explore dimensions, forces, and structures beyond reality.</p><div class="hero-actions"><a class="button primary" href="${sceneUrl('dimensions')}">EXPLORE DIMENSIONS ${icon('arrow')}</a><button class="button secondary" data-action="intro">${icon('play')} WATCH INTRO</button></div><nav class="hero-shortcuts" aria-label="Quick access">${[['cube','DIMENSIONS','dimensions/'],['orbit','GEOMETRIC LAWS','laws/'],['spark','INFINITE STATES','library/?type=presets'],['layers','PURE SIMULATION','simulator/']].map(([i,n,p])=>`<a href="${url(p)}">${icon(i)}${n}</a>`).join('')}</nav></div><aside class="hero-side"><p>GEOMETRY<br>CREATES<br>REALITY</p><nav class="hero-index" aria-label="Section index"><a href="${url('#realms')}">01 &nbsp; REALMS</a><a href="${url('#physical-laws')}">02 &nbsp; LAWS</a><a href="${sceneUrl('geometry')}">03 &nbsp; STRUCTURES</a><a href="${url('simulator/')}">04 &nbsp; SIMULATION</a></nav></aside><div class="scene-caption"><span class="live-dot"></span> A LIVING SYSTEM OF INFINITE POSSIBILITIES</div><div class="hero-tools"><button class="icon-button" data-action="pause" aria-label="Pause all animation">${icon(paused?'play':'pause')}</button><button class="icon-button" data-action="home-camera" aria-label="Reset universe view">${icon('reset')}</button></div></section><div class="container"><section class="features" id="features" aria-label="Geometry laboratories">${scenes.slice(0,4).map((s,i)=>`<a class="feature-card ${s.accent}" href="${sceneUrl(s.id)}"><div class="feature-preview">${art(s.id,true)}</div><div class="feature-info"><div class="card-heading"><h2>${s.title}</h2><span>0${i+1}</span></div><p>${s.description}</p></div><span class="card-arrow" aria-hidden="true">↗</span></a>`).join('')}</section><section class="laws-section" id="physical-laws" aria-labelledby="laws-title"><div class="laws-intro"><span class="section-overline">THE PHYSICAL LAWS</span><h2 id="laws-title">REALITY AS<br>GEOMETRY</h2><p>In this world, everything emerges from geometric rules. Dimension, motion, and structure are unified by a set of elegant mathematical principles.</p><a class="text-link" href="${url('docs/')}">VIEW FULL DOCUMENTATION <span>↗</span></a></div><div><h3>n-DIMENSIONAL SPACE</h3><div class="dimensions-map"><div class="dimension-list">${['Line','Plane','Volume','Tesseract','Hypervolume','Beyond Perception'].map((n,i)=>`<a href="${url('dimensions/?n='+(i+1))}"><strong>${i+1}D</strong>${n}</a>`).join('')}</div><a class="dimension-object" href="${url('dimensions/?n=4')}" aria-label="Open 4D tesseract">${art('dimensions',true)}</a></div></div><div><h3>GEOMETRIC RELATIONSHIPS</h3><a class="equation-link" href="${url('laws/?experiment=distance')}" aria-label="Euclidean distance explained">${icon('cube')}<span>ds² = ∑<small>i=1</small><sup>n</sup> (dx<sub>i</sub>)²</span></a><a class="equation-link" href="${url('docs/#curvature')}" aria-label="Einstein tensor definition">${icon('spark')}<span>G<sub>μν</sub> = R<sub>μν</sub> − ½ Rg<sub>μν</sub></span></a><a class="equation-link" href="${url('laws/?experiment=gravity')}" aria-label="Potential and gravity explained">${icon('orbit')}<span>F = −∇Φ</span></a></div><div><h3>FIELD VISUALIZATION</h3><div class="field-art">${fieldArt()}</div><div class="field-legend" role="group" aria-label="Visual field layers">${['GRAVITY','CURVATURE','ENERGY','WAVE FIELD','GEOMETRY'].map((n,i)=>`<button data-layer="${['gravity','curvature','energy','wave','geometry'][i]}" aria-pressed="true"><i></i>${n}</button>`).join('')}</div></div></section><section class="worlds-section" id="realms" aria-labelledby="realms-title"><div class="section-heading"><a href="${url('library/?type=realms')}"><h2 id="realms-title">EXPLORE THE DIMENSIONAL REALMS <span>↗</span></h2><p>PORTALS TO INFINITE STRUCTURES</p></a><div class="world-controls"><span id="realm-count">01 / 04</span><button class="icon-button" data-action="realm-prev" aria-label="Previous realm">${icon('back')}</button><button class="icon-button" data-action="realm-next" aria-label="Next realm">${icon('arrow')}</button></div></div><div class="realm-grid">${scenes.slice(4).map((s,i)=>`<a class="realm-card ${i===0?'active':''}" href="${sceneUrl(s.id)}" data-realm="${i}" ${i===0?'aria-current="true"':''}><div class="realm-preview">${art(s.id)}</div><div class="realm-copy"><h3>${s.title}</h3><p>${s.eyebrow}</p><span>0${i+1} &nbsp; ↗</span></div></a>`).join('')}</div></section></div></main>`+footer();
 host=new SceneHost(document.querySelector('#home-scene'),'home',{}, {paused});
}
function safeQuery(id,initial){const q=new URLSearchParams(location.search),c=initial||defaultConfig(id);let invalid=false;for(const [key,param] of [['dimension','n'],['projection','projection'],['viewMode','view'],['slice','slice'],['model','model'],['experiment','experiment'],['type','fractal'],['level','level'],['seed','seed']])if(q.has(param)&&key in c.params){const value=q.get(param);c.params[key]=typeof c.params[key]==='number'?Number(value):value;}
 if(c.params.rotationPlanes){const axes='XYZWVU';c.params.rotationPlanes=Object.fromEntries(Object.entries(c.params.rotationPlanes).filter(([plane])=>axes.indexOf(plane[1])<c.params.dimension));}try{return validateConfig(c);}catch(e){invalid=true;queueMicrotask(()=>toast('Invalid address parameter. Safe defaults loaded.'));return defaultConfig(id);}}
function scenePage(id,simulator=false){isSimulator=simulator;sceneId=id;const q=new URLSearchParams(location.search);config=safeQuery(id);
 if(simulator){const preset=presets.find(p=>p.id===q.get('preset'))||presets[0];if(q.has('preset')&&!presets.some(p=>p.id===q.get('preset')))queueMicrotask(()=>toast('Unknown preset. Hypercube 4D loaded.'));sceneId=preset.sceneId;config=defaultConfig(sceneId);Object.assign(config.params,preset.params);config=safeQuery(sceneId,config);}
 if(q.has('local')){try{const record=readWorks().find(w=>w.id===q.get('local'));if(!record)throw Error('Local work not found in this browser.');config=validateConfig(record.config);sceneId=config.sceneId;}catch(e){queueMicrotask(()=>toast(e.message));}}
 const s=byId[sceneId];document.title=(simulator?'Simulation Workbench':s.name)+' — POLYVERSE';
 app.innerHTML=header()+`<main class="scene-page"><div class="scene-titlebar"><div><div class="breadcrumbs"><a href="${url(s.path.startsWith('realms')?'#realms':'#features')}" data-return>← RETURN TO UNIVERSE</a><span>/</span><span>${simulator?'SIMULATOR':'INTERACTIVE LABORATORY'}</span></div><h1 id="scene-page-title">${simulator?'SIMULATION WORKBENCH':s.title}</h1></div><div class="scene-title-actions"><a class="button secondary compact" id="related-link" href="${sceneUrl(s.related)}">${byId[s.related].name} ↗</a><button class="icon-button" data-action="share" aria-label="Copy share link">${icon('share')}</button><button class="icon-button" data-action="help" aria-label="Scene controls and help">${icon('help')}</button><button class="icon-button mobile-params" data-action="parameters" aria-label="Toggle parameters">${icon('layers')}</button></div></div><div class="workspace ${simulator?'simulator-workspace':''}">${simulator?`<aside class="preset-sidebar" aria-label="Simulation presets"><h2>SCENE PRESETS</h2>${presets.map((p,i)=>`<button class="preset-button ${p.sceneId===sceneId?'active':''}" data-preset="${p.id}">${icon(['cube','spark','orbit','layers','cube','orbit','spark','layers'][i])}<span>${p.name}<small>0${i+1} / ${byId[p.sceneId].title}</small></span></button>`).join('')}</aside>`:''}<section class="scene-viewport" id="scene-viewport" aria-label="Interactive 3D observation area"><div class="viewport-overlay"><p class="eyebrow" id="scene-eyebrow">${s.eyebrow}</p><p class="viewport-description" id="scene-description">${s.description}</p></div><div class="statistics" id="statistics" aria-live="off"></div><div class="viewport-bottom"><span class="live-dot"></span> <span id="live-state">${paused?'PAUSED · MANUAL OBSERVATION':'LIVE · REAL-TIME GEOMETRY'}</span><br>DRAG TO ORBIT · SCROLL TO ZOOM</div><div class="camera-buttons" role="group" aria-label="Camera controls"><button class="icon-button" data-camera="left" aria-label="Rotate camera left">←</button><button class="icon-button" data-camera="up" aria-label="Rotate camera up">↑</button><button class="icon-button" data-camera="in" aria-label="Zoom in">+</button><button class="icon-button" data-camera="right" aria-label="Rotate camera right">→</button><button class="icon-button" data-camera="down" aria-label="Rotate camera down">↓</button><button class="icon-button" data-camera="out" aria-label="Zoom out">−</button><button class="icon-button" data-camera="pan-left" aria-label="Pan left">⇤</button><button class="icon-button" data-action="camera-reset" aria-label="Reset camera">⌾</button><button class="icon-button" data-camera="pan-right" aria-label="Pan right">⇥</button></div></section><aside class="parameters" id="parameters" aria-label="Scene parameters">${panel(sceneId,config.params)}</aside></div><div class="scene-toolbar"><button class="button primary" data-action="pause">${icon(paused?'play':'pause')}<span>${paused?'PLAY':'PAUSE'}</span></button><button class="button secondary" data-action="step" ${['motion','orbital'].includes(sceneId)?'':'hidden'}>${icon('step')} STEP</button><span class="toolbar-time" id="simulation-time">t = 0.000</span><button class="button secondary" data-action="reset">${icon('reset')} RESET SCENE</button><button class="button secondary" data-action="camera-reset">RESET VIEW</button><span class="toolbar-spacer"></span><button class="icon-button" data-action="save" aria-label="Save local work">${icon('save')}</button><button class="icon-button" data-action="export" aria-label="Export configuration JSON">${icon('download')}</button><button class="icon-button" data-action="import" aria-label="Import configuration JSON">${icon('layers')}</button><button class="icon-button" data-action="screenshot" aria-label="Export scene image">${icon('image')}</button><button class="icon-button" data-action="fullscreen" aria-label="Toggle fullscreen">${icon('expand')}</button></div></main>`;
 host=new SceneHost(document.querySelector('#scene-viewport'),sceneId,config.params,{paused,quality:config.quality,layers:config.layers,onUpdate:updateStats,onSelect:showSelection});host.applyCamera(config.camera);fillObjects();document.querySelector('#quality').value=config.quality;document.querySelector('#base-grid').checked=config.layers.geometry;
 const returnLink=document.querySelector('[data-return]');returnLink.onclick=e=>{if(document.referrer&&new URL(document.referrer).origin===location.origin&&history.length>1){e.preventDefault();history.back();}};
}
function updateStats(stats){const el=document.querySelector('#statistics');if(!el)return;el.innerHTML=Object.entries(stats).map(([key,value])=>`<div class="stat-row"><span>${esc(key.replace(/([A-Z])/g,' $1'))}</span><strong>${esc(value)}</strong></div>`).join('');const t=document.querySelector('#simulation-time');let scale=document.querySelector('.energy-scale');if(sceneId==='laws'&&config?.params.experiment==='gravity'){if(!scale){scale=document.createElement('div');scale.className='energy-scale';scale.innerHTML='<span>POTENTIAL ENERGY</span><i></i><small>LOWER &nbsp; → &nbsp; HIGHER</small>';document.querySelector('#scene-viewport').append(scale);}scale.hidden=!config.params.energy;}else scale?.remove();const sliceInput=document.querySelector('[data-param=slice]'),bounds=host?.model.sliceRange?.();if(sliceInput&&bounds){sliceInput.min=bounds[0].toFixed(2);sliceInput.max=bounds[1].toFixed(2);sliceInput.setAttribute('aria-valuemin',sliceInput.min);sliceInput.setAttribute('aria-valuemax',sliceInput.max);}if(t)t.textContent='t = '+(host?.model.physics?.time??host?.time??0).toFixed(3)+' u';}
function fillObjects(){const grid=document.querySelector('#base-grid');if(grid)grid.checked=config.layers.geometry;const quality=document.querySelector('#quality');if(quality)quality.value=config.quality;const select=document.querySelector('#object-select');if(!select)return;const objects=host?.model.objects?.()||[];select.innerHTML='<option value="">Click geometry or choose an object</option>'+objects.map(o=>`<option value="${o.type}:${o.index}">${esc(o.name)}</option>`).join('');const current=host?.model.selection?.();if(current)select.value=current.type+':'+current.index;select.disabled=!objects.length;if(!objects.length)select.firstChild.textContent='No selectable objects in this scene';}
function showSelection(data){const el=document.querySelector('#selection-info');if(!el)return;el.textContent=data?JSON.stringify(data,(_,v)=>typeof v==='number'?Number(v.toFixed(5)):v,2):'No object selected. Use the scene or the list above.';if(data){const select=document.querySelector('#object-select');select.value=data.type+':'+data.index;}const editor=document.querySelector('#body-editor');if(editor&&data?.type==='body'&&config.params.preset==='analytic'){editor.innerHTML='<p class="fine-print">Positions and vectors come from a parameter curve. Choose the numerical model to edit mass and initial conditions.</p>';return;}if(editor&&data?.type==='body'&&editor.dataset.index!==String(data.index)){editor.innerHTML=bodyEditor(data);editor.dataset.index=String(data.index);}else if(editor&&data?.type==='body'&&!editor.contains(document.activeElement)){for(const el of editor.querySelectorAll('[data-body]')){const key=el.dataset.body;el.value=key==='mass'?data.mass:data[key[0]==='p'?'position':'velocity']['xyz'.indexOf(key[1])].toFixed(3);}}else if(editor&&data?.type!=='body'){editor.innerHTML='';delete editor.dataset.index;}}
function changePreset(presetId){const preset=presets.find(p=>p.id===presetId);if(!preset)return;try{sessionStorage.setItem('polyverse.draft.'+sceneId,JSON.stringify(currentConfig()));}catch{}exitWalk();sceneId=preset.sceneId;config=defaultConfig(sceneId);Object.assign(config.params,preset.params);host.rebuild(config.params,sceneId);host.applyLayers(config.layers);host.resetCamera();document.querySelector('#parameters').innerHTML=panel(sceneId,config.params);document.querySelector('#scene-eyebrow').textContent=byId[sceneId].eyebrow;document.querySelector('#scene-description').textContent=byId[sceneId].description;document.querySelectorAll('[data-preset]').forEach(b=>b.classList.toggle('active',b.dataset.preset===presetId));const link=document.querySelector('#related-link');link.href=sceneUrl(byId[sceneId].related);link.textContent=byId[byId[sceneId].related].name+' ↗';document.querySelector('[data-action=step]').hidden=!['motion','orbital'].includes(sceneId);fillObjects();const u=new URL(location);u.search='?preset='+presetId;history.replaceState({},'',u);}
function currentConfig(){const c=structuredClone(config);c.camera=host?.exportCamera();c.layers={geometry:host?.layers?.geometry!==false,labels:config.params.labels??false};c.quality=['auto','low','medium','high'].includes(host?.quality)?host.quality:'auto';if(host?.model.physics&&config.params.preset!=='analytic')c.params.bodyStates=host.model.physics.bodies.map(b=>({m:b.m,p:b.p.slice(),v:b.v.slice()}));return validateConfig(c);}
function syncURL(){const u=new URL(location),p=config.params;const q=new URLSearchParams();if(isSimulator)q.set('preset',presets.find(p=>p.sceneId===sceneId)?.id||presets[0].id);if(p.dimension)q.set('n',p.dimension);if(p.projection)q.set('projection',p.projection);if(p.model)q.set('model',p.model);if(p.experiment)q.set('experiment',p.experiment);if(p.viewMode==='slice'){q.set('view','slice');q.set('slice',p.slice);}if(p.type){q.set('fractal',p.type);q.set('level',p.level);}u.search=q.toString();history.replaceState({},'',u);}
function setPaused(value){paused=value;host?.setPaused(value);document.documentElement.dataset.paused=String(value);try{sessionStorage.setItem('polyverse.paused',JSON.stringify(value));}catch{}document.querySelectorAll('[data-action=pause]').forEach(b=>{if(b.classList.contains('button'))b.innerHTML=icon(value?'play':'pause')+`<span>${value?'PLAY':'PAUSE'}</span>`;else b.innerHTML=icon(value?'play':'pause');b.setAttribute('aria-label',value?'Play all animation':'Pause all animation');});const state=document.querySelector('#live-state');if(state)state.textContent=value?'PAUSED · MANUAL OBSERVATION':'LIVE · REAL-TIME GEOMETRY';}
function toast(message){let el=document.querySelector('#toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,6500);}
function openDialog(title,body,klass=''){closeDialog();dialogReturn=document.activeElement;const d=document.createElement('dialog');d.className=klass;d.innerHTML=`<div class="dialog-top"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;document.body.append(d);d.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});d.showModal();return d;}
function closeDialog(){const d=document.querySelector('dialog');if(!d)return;if(intro){clearInterval(intro.timer);intro=null;host?.rebuild({},'home');host?.resetCamera();host?.setPaused(paused);}d.close();d.remove();dialogReturn?.focus();}
// Search inputs consume their first native Escape to clear text. The dialog's
// close gesture must also work while that input owns focus.
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.querySelector('dialog')){event.preventDefault();event.stopImmediatePropagation();closeDialog();}},true);
function searchText(...parts){const translate=globalThis.window?.strgoI18n?.translate;return parts.flatMap(part=>{const value=String(part||'');return translate?[value,...['zh-CN','zh-TW','en','ja','ko'].map(locale=>translate(value,locale))]:[value];}).join(' ').toLowerCase();}
function resultsMarkup(q,limit=30){const words=q.toLowerCase().trim().split(/\s+/);const found=searchEntries.filter(e=>words.every(w=>searchText(e.title,e.description,e.type).includes(w))).slice(0,limit);return `<p class="result-count">${found.length} RESULTS ${q?'FOR “'+esc(q)+'”':''}</p><div class="search-results">${found.length?found.map((r,i)=>`<a class="search-result ${i===0?'selected':''}" href="${url(r.path)}"><strong>${esc(r.title)}</strong><small>${esc(r.type.toUpperCase())} &nbsp; / &nbsp; ${esc(r.description)}</small></a>`).join(''):'<p class="empty-state">No matching structures. Try “gravity”, “cube” or “wave”.</p>'}</div>`;}
function openSearch(){const initial=new URLSearchParams(location.search).get('q')||'';const d=openDialog('SEARCH THE POLYVERSE',`<form id="search-form"><label class="dialog-label" for="search-input">Models, worlds, laws & documentation</label><input id="search-input" type="search" placeholder="What will you discover?" autocomplete="off" name="q" value="${esc(initial)}"><button class="screen-reader-only">Search</button></form><div id="search-results">${resultsMarkup(initial,initial?30:8)}</div><p class="fine-print">↑ ↓ Select · Enter Open · Esc Close</p>`);d.querySelector('input').focus();}
function startIntro(){if(route){location.href=url('?intro=1');return;}const stages=[['PURE GEOMETRY','A universe built from nested cubes, light and mathematical form.','home'],['MOTION WITHOUT END','Three-dimensional trajectories, sampled from a fixed-step gravitational simulation.','orbital'],['SELF-SIMILAR WORLDS','Each tetrahedron becomes four smaller tetrahedra. A recursive structure you can explore.','fractal'],['BEYOND PERCEPTION','Real four-dimensional coordinates, rotated and projected into three-dimensional space.','higher']];const d=openDialog('A SCENE TOUR · 24 SECONDS',`<div class="intro-progress">${stages.map(()=>'<span></span>').join('')}</div><p class="eyebrow">A PROCEDURAL SCENE TOUR · 场景导览</p><h3 class="intro-stage"></h3><p class="intro-description"></p><div class="dialog-actions"><button class="button secondary" data-action="intro-pause">${icon('pause')} PAUSE TOUR</button><button class="button secondary" data-action="intro-replay">${icon('reset')} REPLAY</button><button class="button primary" data-action="close">SKIP TOUR ${icon('arrow')}</button></div>`,'intro-dialog');intro={stages,stage:-1,elapsed:0,paused:paused,last:performance.now()};if(paused)d.querySelector('[data-action=intro-pause]').innerHTML=icon('play')+'PLAY TOUR';const step=()=>{if(!intro)return;const now=performance.now(),dt=(now-intro.last)/1000;intro.last=now;if(!intro.paused&&!paused&&!document.hidden)intro.elapsed+=dt;const idx=Math.min(3,Math.floor(intro.elapsed/6));if(idx!==intro.stage){intro.stage=idx;const [title,description,id]=stages[idx];d.querySelector('.intro-stage').textContent=title;d.querySelector('.intro-description').textContent=description;d.querySelectorAll('.intro-progress span').forEach((s,i)=>s.classList.toggle('active',i<=idx));host.rebuild(id==='home'?{}:structuredClone(byId[id].defaults),id);host.resetCamera();}if(intro.elapsed>=24){intro.paused=true;d.querySelector('[data-action=intro-pause]').textContent='TOUR COMPLETE';}};step();intro.timer=setInterval(step,100);}
function library(){document.title='Library — POLYVERSE';filter=new URLSearchParams(location.search).get('type')||'all';if(!['all','realms','models','laws','presets','local'].includes(filter))filter='all';app.innerHTML=header()+`<main class="page-main"><div class="page-hero"><p class="eyebrow">AN ATLAS OF POSSIBILITIES</p><h1>THE GEOMETRIC LIBRARY</h1><p>Enter a world. Study a structure. Continue a thought.<br>Your next discovery is one configuration away.</p></div><div class="library-tools"><div class="filter-buttons" role="group" aria-label="Library category">${[['all','ALL'],['realms','WORLDS'],['models','MODELS'],['laws','LAWS'],['presets','PRESETS'],['local','LOCAL SAVES']].map(([id,n])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${n}</button>`).join('')}</div><input class="library-search" id="library-search" type="search" placeholder="Search the library…" aria-label="Search library"></div><div id="library-grid" class="library-grid"></div><p class="fine-print">Local works live only in this browser. Export JSON to keep a portable copy; there is no cloud account or synchronization.</p></main>`+footer();renderLibrary();}
function renderLibrary(){let locals=[];try{locals=readWorks();}catch(e){toast(e.message);}const entries=[...searchEntries.filter(e=>e.type!=='docs').map(e=>({...e,sceneId:scenes.find(s=>e.path.startsWith(s.path))?.id||presets.find(p=>e.path.endsWith(p.id))?.sceneId||'laws'})),...locals.map(w=>({title:w.name,description:'Local configuration · '+new Date(w.created).toLocaleDateString(),path:'simulator/?local='+encodeURIComponent(w.id),type:'local',sceneId:w.config.sceneId,localId:w.id}))].filter(e=>(filter==='all'||e.type===filter)&&(e.localId?(e.title+' '+e.description).toLowerCase():searchText(e.title,e.description)).includes(query.toLowerCase()));document.querySelector('#library-grid').innerHTML=entries.length?entries.map(e=>`<article class="library-card"><a href="${url(e.path)}"><div class="realm-preview">${art(e.sceneId)}</div><div class="library-card-body"><h2 ${e.localId?'data-strgo-user-content':''}>${esc(e.title)}</h2><p>${esc(e.description)}</p><small>${esc(e.type.toUpperCase())} &nbsp; ↗ OPEN STUDY</small></div></a>${e.localId?`<div class="local-actions"><button data-rename="${esc(e.localId)}">Rename</button><button data-delete="${esc(e.localId)}">Delete</button><button data-export-work="${esc(e.localId)}">Export</button></div>`:''}</article>`).join(''):'<div class="empty-state">'+(filter==='local'?'No local works yet. Open a scene and choose Save to begin.':'No matching entries. Try another category or name.')+'</div>';}
function about(){document.title='About — POLYVERSE';app.innerHTML=header()+`<main class="page-main"><div class="about-grid"><div class="page-hero"><p class="eyebrow">A THOUGHT EXPERIMENT, MADE VISIBLE</p><h1>REALITY BEGINS<br>WITH A RULE.</h1><p>POLYVERSE is an interactive universe of geometric structures. Move through ordered cities, observe gravity and discover what a fourth dimension can look like.</p><p style="margin-top:20px">Every structure is generated from coordinates. Every numerical trajectory comes from the model’s state. The beauty is in seeing the rules become space.</p><div class="hero-actions"><a class="button primary" href="${sceneUrl('dimensions')}">START EXPLORING ${icon('arrow')}</a><a class="button secondary" href="${url('docs/')}">READ THE MODELS</a></div></div><div class="about-visual">${art('higher')}</div></div><div class="about-facts"><div><strong>06</strong><span>DIMENSIONS TO EXPLORE</span></div><div><strong>08</strong><span>INDEPENDENT REAL-TIME SCENES</span></div><div><strong>∞</strong><span>POSSIBLE QUESTIONS</span></div></div><article class="document" style="margin-top:60px"><section><h2>Made to be explored</h2><p>Drag the scene to rotate, scroll to zoom, or use the camera buttons. Each laboratory has named parameters, live model statistics and a keyboard-accessible object list. Pause any time and continue observing by hand.</p></section><section><h2>Mathematics, with clear boundaries</h2><p>Higher-dimensional models use real 1D–6D coordinates and sequential projection. Gravity is a softened Newtonian demonstration in normalized units. Scalar waves and harmonic oscillators are simplified models; no general relativity solver is included. Portal travel is a three-dimensional visual narrative.</p></section><section><h2>An independent exploration</h2><p>This project makes no claims of institutional research or physical discovery. Geometry and previews are generated in code. Your saved studies remain in your browser; portable configurations use plain JSON.</p></section></article></main>`+footer();}
const docSections=[['getting-started','Getting started'],['projection','Coordinates & projection'],['slicing','Four-dimensional slicing'],['dynamics','Motion & physical parameters'],['curvature','Formulas & model limits'],['performance','Performance & accessibility'],['configuration','Saving & configuration'],['troubleshooting','Troubleshooting']];
function docs(){document.title='Documentation — POLYVERSE';app.innerHTML=header()+`<main class="page-main"><div class="page-hero"><p class="eyebrow">UNDERSTAND THE RULES</p><h1>FIELD NOTES & DOCUMENTATION</h1><p>A practical guide to the coordinates, models and interactions behind this universe.</p></div><div class="document-layout"><nav class="doc-toc" aria-label="Document contents">${docSections.map(([id,n])=>`<a href="#${id}">${n}</a>`).join('')}<a href="${url('search/?q=')}" >Search documentation ↗</a><a href="${url('')}">← Return home</a></nav><article class="document"><section id="getting-started"><h2>01 / Getting started</h2><p>Choose any of the eight laboratories and worlds. All have their own URL and live three-dimensional scene. Drag to orbit, scroll to zoom, right-drag to pan. The camera buttons provide keyboard equivalents. On touch devices, select “Start observing” to activate 3D gestures, then “Finish observing” to scroll normally.</p><p>Pause freezes display time and simulated time. Manual camera movement and parameter editing remain available. Reset Scene restores the preset; Reset View restores only the camera. Shift + drag in a paused dynamics scene moves the selected body on a horizontal plane. The object list can select overlapping geometry.</p><p><a href="${url('simulator/')}">Open the simulator</a> for eight ready-to-run presets, configuration export, image export and browser-local works.</p></section><section id="projection"><h2>02 / Coordinates & projection</h2><p>An n-hypercube has vertices in {−1,+1}<sup>n</sup>. An edge connects vertices that differ in exactly one coordinate. The model has 2<sup>n</sup> vertices and n × 2<sup>n−1</sup> edges. “Beyond Perception” is a visual title, not a standard dimension name.</p><table><tr><th>Dimension</th><th>Vertices</th><th>Edges</th><th>Projection</th></tr>${[1,2,3,4,5,6].map(n=>`<tr><td>${n}D</td><td>${2**n}</td><td>${n*2**(n-1)}</td><td>${n<4?'Embedded in 3D':Array.from({length:n-2},(_,i)=>(n-i)+'D').join(' → ')}</td></tr>`).join('')}</table><p>Rotation in plane AB applies x′ = x cos θ − y sin θ and y′ = x sin θ + y cos θ. Each frame starts with immutable base vertices. The 3D camera and n-dimensional rotation are independent.</p><p>Orthographic projection drops the last coordinate. Perspective projection uses x′ = x d / (d − w), repeatedly, until three coordinates remain. At each stage d = 3B, beginning with B = √n; the next conservative bound is B d/(d−B). Original edge lengths remain 2, even when projected lengths vary.</p><p><a href="${sceneUrl('dimensions')}">Inspect original, rotated and projected coordinates →</a></p></section><section id="slicing"><h2>03 / Four-dimensional slicing</h2><p>The 4D slice intersects the rotated tesseract with w = c. The 32 original edges are checked for crossings, with interpolation and tolerance-based deduplication. Coincident vertices and edges are included explicitly. A 3D convex hull creates the boundary; lower-rank results use a point, line or planar polygon.</p><p>Restore the standard pose, pause, choose Slice and set c = 0. The result is a cube with original edge length 2 (displayed at a uniform 1.8× scale). At c = ±1 the boundary cube remains. For |c| &gt; 1 the slice is empty. Rotate XW or YW to change the cross section. The live w range is shown in the inspector.</p><p>5D and 6D use multi-step projection. They do not claim to show a complete three-dimensional slice.</p></section><section id="dynamics"><h2>04 / Motion & physical parameters</h2><p>All masses, lengths and times use normalized demonstration units. Numerical scenes calculate pairwise softened Newtonian gravity:</p><pre>aᵢ = Σⱼ Gmⱼ (rⱼ − rᵢ) / (|rⱼ − rᵢ|² + ε²)^(3/2)</pre><p>ε is strictly positive. Velocity Verlet updates all half-step velocities, then all positions, recalculates all accelerations, then completes the velocity update. The fixed time step is 1/120. Each rendered frame contributes at most 1/15 second and 16 substeps. Excess work slows the simulation rather than taking a large unstable step.</p><p>Trails sample actual positions every four ticks and retain up to 1024 points. K = Σ ½mv²; U = −Σᵢ&lt;ⱼ Gmᵢmⱼ/√(r²+ε²). The energy error uses the initial baseline and a safe near-zero denominator. Editing mass, position, velocity, G or ε rebuilds that baseline and clears trails.</p><p>Pause stops position, velocity and simulation time. Step advances exactly one dt. Hidden pages discard accumulated time and do not catch up on return. Analytic Orbit is labeled separately and excludes energy accuracy claims. The default models have no damping or collision merging.</p><p>Harmonic motion uses a = −kx/m; scalar waves use u = A sin(kx + kz − ωt). Visual layer switches affect visibility only. Gravity arrows are independent from the underlying force calculation.</p></section><section id="curvature"><h2>05 / Formulas & model limits</h2><p>ds² = Σ(dxᵢ)² is the Euclidean line element. G<sub>μν</sub> = R<sub>μν</sub> − ½Rg<sub>μν</sub> defines the Einstein tensor; it is not the complete Einstein field equation. The potential mesh is an explanatory visualization and does not solve spacetime curvature.</p><p>F = −∇Φ uses Φ as potential energy. A potential per unit mass instead gives acceleration through its negative gradient. The numerical force module uses masses explicitly.</p><p>Face Separation moves polyhedron faces along their normals. It is not a standard non-overlapping unfolding net. Triangulation edges do not count toward the original polyhedron topology. Fractals are finite structures: Sierpinski has 4<sup>L</sup> tetrahedra, Menger has 20<sup>L</sup> retained cubes.</p></section><section id="performance"><h2>06 / Performance & accessibility</h2><p>There is one active WebGL renderer. Buildings and fractals use InstancedMesh; stars use Points. Auto quality reduces pixel ratio and disables bloom when sustained rendering falls below the target. Rendering quality never deletes physics bodies. Desktop recursion caps: Sierpinski 5, Menger 3; touch-width devices: 4 and 2.</p><p>Reduced-motion preferences start the whole site paused. The global pause also stops CSS previews, particles and automatic camera behavior. All navigation uses native links; text, controls and model statistics remain HTML. Screens below 800px in height scroll naturally.</p><p>Quality settings are rendering budgets, not a frame-rate guarantee. The included test record reports measurements on the available software-rendering environment; it cannot certify 60fps on every device.</p></section><section id="configuration"><h2>07 / Saving & configuration</h2><p>Save creates a named record in this browser. Local Saves allows opening, renaming, exporting and deleting that exact record. Deletion requires its name. JSON contains schemaVersion, sceneId, seed, whitelisted params, camera, layers and quality. Exported dynamics states become initial conditions at time zero, not running snapshots.</p><p>Imports are limited to 256 KB, supported scene IDs, bounded finite numbers and at most eight bodies. Unknown fields in params are rejected. Names are inserted as text. Invalid imports keep the current scene. Browser storage failure offers JSON export. Future schema versions are rejected without overwriting the original file.</p><p>Share links encode a supported preset or scene and a small set of address parameters. Local work IDs only resolve in the current browser. Use JSON to share a complete configuration.</p></section><section id="troubleshooting"><h2>08 / Troubleshooting</h2><p>If WebGL is unavailable, a procedural static preview appears while links, configuration controls and JSON export remain available. Retry after enabling hardware acceleration. Context loss pauses the scene and waits for restoration. Choose Low quality for reduced GPU load.</p><p>If an imported value is invalid, the error identifies the field and range. Correct the JSON and retry. Unknown URLs show a recovery page. Direct deep links work because every supported path has its own index.html.</p><p>Run with HTTP: <code>npm run dev</code>. Build for deployment: <code>npm run build</code>. For a subdirectory: <code>BASE_PATH=/polyverse/ npm run build</code>. Serve the generated dist directory; do not use file:// as the only launch method.</p></section></article></div></main>`+footer();}
function searchPage(){document.title='Search — POLYVERSE';query=new URLSearchParams(location.search).get('q')||'';app.innerHTML=header()+`<main class="page-main"><div class="page-hero"><p class="eyebrow">FOLLOW YOUR CURIOSITY</p><h1>SEARCH THE POLYVERSE</h1><p>Find a model, a world, a physical law or a field note.</p></div><form id="page-search-form"><label class="dialog-label" for="page-search">Search models, worlds, laws and documentation</label><input type="search" id="page-search" name="q" placeholder="Try gravity, fractal or projection" value="${esc(query)}"></form><div id="page-search-results">${resultsMarkup(query)}</div></main>`+footer();}
function notFound(){document.title='Unknown coordinates — POLYVERSE';app.innerHTML=header()+`<main class="page-main"><div class="page-hero"><p class="eyebrow">404 / UNKNOWN COORDINATES</p><h1>BEYOND THE MAP.</h1><p>This location has no geometry yet. Return to a known part of the universe.</p><div class="hero-actions"><a class="button primary" href="${url('')}">RETURN HOME ${icon('arrow')}</a><a class="button secondary" href="${url('library/')}">OPEN LIBRARY</a></div></div><div style="max-width:500px">${art('higher')}</div></main>`+footer();}
function exitWalk(){if(!walk)return;document.removeEventListener('keydown',walk.listener);walk=null;document.querySelector('.walk-indicator')?.remove();if(document.pointerLockElement)document.exitPointerLock();if(host?.controls)host.controls.enabled=true;host?.resetCamera();}
function enterWalk(){if(!host.camera)return;if(walk){exitWalk();return;}setPaused(true);host.controls.enabled=false;let z=8,yaw=0;host.camera.position.set(0,-1.4,z);const update=()=>{host.camera.position.set(0,-1.4,z);host.camera.lookAt(Math.sin(yaw)*4,-1.4,z-Math.cos(yaw)*4);host.render();};const listener=e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['w','W','ArrowUp'].includes(e.key))z=Math.max(-12,z-.4);if(['s','S','ArrowDown'].includes(e.key))z=Math.min(12,z+.4);if(['a','A','ArrowLeft'].includes(e.key))yaw-=.12;if(['d','D','ArrowRight'].includes(e.key))yaw+=.12;if(e.key==='Escape'){exitWalk();return;}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key))e.preventDefault();update();};walk={listener};document.addEventListener('keydown',listener);const b=document.createElement('button');b.className='walk-indicator';b.textContent='STREET WALK · W/S move · A/D look · Esc / click to exit';b.onclick=exitWalk;host.container.append(b);update();}
// Native page links are left to the browser; only controls are delegated.
document.addEventListener('click',async e=>{
 const camera=e.target.closest('[data-camera]');if(camera){host?.cameraAction(camera.dataset.camera);return;}
 const layer=e.target.closest('[data-layer]');if(layer){const active=layer.getAttribute('aria-pressed')!=='true';layer.setAttribute('aria-pressed',active);document.querySelector(`[data-field=${layer.dataset.layer}]`).style.display=active?'':'none';return;}
 const preset=e.target.closest('[data-preset]');if(preset){changePreset(preset.dataset.preset);return;}
 const category=e.target.closest('[data-filter]');if(category){filter=category.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===category));const u=new URL(location);u.search='?type='+filter;history.replaceState({},'',u);renderLibrary();return;}
 const edit=e.target.closest('[data-rename],[data-delete],[data-export-work]');if(edit){try{const key=edit.dataset.rename||edit.dataset.delete||edit.dataset.exportWork,item=readWorks().find(w=>w.id===key);if(!item)throw Error('Work no longer exists.');if(edit.dataset.exportWork){download(JSON.stringify(item.config,null,2),'polyverse-work.json');return;}const deleting=!!edit.dataset.delete;const d=openDialog(deleting?'DELETE LOCAL WORK':'RENAME LOCAL WORK',`<p class="dialog-copy"><span>${deleting?'Type the exact name to delete this work:':'Choose a new name for this work:'}</span> “<span data-strgo-user-content>${esc(item.name)}</span>”.${deleting?' <span>This removes only this local record.</span>':''}</p><form id="edit-work-form"><label class="dialog-label" for="work-name">${deleting?'Confirm name':'New name'}</label><input id="work-name" maxlength="80" required value="${deleting?'':esc(item.name)}"><div class="dialog-actions"><button class="button primary" type="submit">${deleting?'DELETE THIS WORK':'SAVE NAME'}</button><button class="button secondary" type="button" data-action="close">CANCEL</button></div></form>`);d.querySelector('form').onsubmit=ev=>{ev.preventDefault();const name=d.querySelector('input').value.trim();if(deleting&&name!==item.name){toast('Name does not match. The work was kept.');return;}try{const all=readWorks();writeWorks(deleting?all.filter(w=>w.id!==item.id):all.map(w=>w.id===item.id?{...w,name:name||'Untitled study'}:w));closeDialog();renderLibrary();toast(deleting?'Local work deleted.':'Work renamed.');}catch(err){toast(err.message);}};}catch(err){toast(err.message);}return;}
 const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
 try{
 if(action==='menu'){const menu=document.querySelector('.mobile-menu');menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',!menu.hidden);if(!menu.hidden)menu.querySelector('a').focus();}
 if(action==='search')openSearch();if(action==='close')closeDialog();if(action==='pause')setPaused(!paused);if(action==='intro')startIntro();
 if(action==='intro-pause'&&intro){intro.paused=!intro.paused;if(!intro.paused)setPaused(false);host.setPaused(intro.paused||paused);button.innerHTML=icon(intro.paused?'play':'pause')+(intro.paused?'PLAY TOUR':'PAUSE TOUR');}
 if(action==='intro-replay'&&intro){intro.elapsed=0;intro.stage=-1;intro.paused=false;setPaused(false);host.setPaused(false);}
 if(action==='home-camera'||action==='camera-reset'){exitWalk();host?.resetCamera();}
 if(action==='realm-prev'||action==='realm-next'){activeRealm=(activeRealm+(action==='realm-next'?1:3))%4;document.querySelectorAll('[data-realm]').forEach((c,i)=>{c.classList.toggle('active',i===activeRealm);if(i===activeRealm)c.setAttribute('aria-current','true');else c.removeAttribute('aria-current');});document.querySelector('#realm-count').textContent='0'+(activeRealm+1)+' / 04';if(innerWidth<768)document.querySelector(`[data-realm="${activeRealm}"]`).scrollIntoView({behavior:paused?'instant':'smooth',block:'nearest',inline:'start'});}
 if(action==='community')openDialog('THE POLYVERSE COMMUNITY','<p class="dialog-copy">There are no official social accounts configured for this independent project. The icons here open this information panel.</p><p class="dialog-copy">Continue exploring, save a study locally, or export a configuration to share your own discovery.</p><div class="dialog-actions"><a class="button primary" href="'+url('library/')+'">OPEN THE LIBRARY ↗</a></div>');
 if(action==='help')openDialog('OBSERVATION GUIDE','<p class="dialog-copy">Drag to orbit · Scroll to zoom · Right-drag to pan. Use the arrow, + / − and pan buttons for keyboard operation. On touch screens, tap Start observing first.</p><p class="dialog-copy">Pause freezes all automatic motion. Parameters and the camera remain editable. In motion scenes, select a body then edit its mass, position or velocity. While paused, Shift + drag moves it on its horizontal plane. The same gesture moves a selected point in the distance experiment. Step advances exactly 1/120 of a simulation unit.</p><p class="dialog-copy">Reset Scene restores parameters. Reset View restores the camera only. All units are normalized demonstration units.</p><a class="button primary" href="'+url('docs/')+'">FULL DOCUMENTATION ↗</a>');
 if(action==='parameters'){document.querySelector('.scene-page').classList.toggle('panel-collapsed');host.resize();}
 if(action==='walk')enterWalk();
 if(action==='step'){setPaused(true);host.step();}
 if(action==='standard'){setPaused(true);config.params.rotationPlanes={};config.params.slice=0;host.rebuild(config.params);host.applyLayers(config.layers);document.querySelector('#parameters').innerHTML=panel(sceneId,config.params);fillObjects();}
 if(action==='reset'){exitWalk();const preset=presets.find(p=>p.id===new URLSearchParams(location.search).get('preset'));config=defaultConfig(sceneId);if(preset?.sceneId===sceneId)Object.assign(config.params,preset.params);host.rebuild(config.params);host.applyLayers(config.layers);document.querySelector('#parameters').innerHTML=panel(sceneId,config.params);fillObjects();syncURL();toast('Scene and parameters restored.');}
 if(action==='copy-coordinates'){const value=host.model.selection?.();if(!value){toast('Select an object first.');return;}await copyText(JSON.stringify(value,null,2));toast('Selected coordinates copied.');}
 if(action==='screenshot')host.screenshot();
 if(action==='export'){download(JSON.stringify(currentConfig(),null,2),'polyverse-'+sceneId+'.json');toast('Configuration exported · initial state at time zero.');}
 if(action==='save'){const d=openDialog('SAVE A LOCAL STUDY',`<p class="dialog-copy">Saved only in this browser. Export JSON for a portable copy.</p><form id="save-form"><label class="dialog-label" for="save-name">Study name</label><input id="save-name" maxlength="80" value="${esc(byId[sceneId].name)}" required><div class="dialog-actions"><button class="button primary" type="submit">SAVE STUDY ${icon('save')}</button><button class="button secondary" type="button" data-action="close">CANCEL</button></div></form>`);d.querySelector('form').onsubmit=ev=>{ev.preventDefault();try{saveWork(d.querySelector('input').value,currentConfig());closeDialog();toast('Study saved in this browser. Open Library → Local Saves to continue.');}catch(err){toast(err.message+' Use Export JSON.');}};}
 if(action==='import'){const d=openDialog('IMPORT CONFIGURATION','<p class="dialog-copy">Choose a POLYVERSE JSON configuration, up to 256 KB. The current scene stays intact if validation fails.</p><label class="dialog-label" for="import-file">Configuration JSON</label><input id="import-file" type="file" accept=".json,application/json"><p id="import-message" class="dialog-copy" role="status"></p>');d.querySelector('input').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>262144)throw Error('file: maximum 256 KB.');const next=validateConfig(JSON.parse(await f.text()));config=next;sceneId=next.sceneId;exitWalk();host.rebuild(config.params,sceneId);host.applyLayers(config.layers);host.applyCamera(config.camera);document.querySelector('#parameters').innerHTML=panel(sceneId,config.params);fillObjects();document.querySelector('#scene-eyebrow').textContent=byId[sceneId].eyebrow;document.querySelector('#scene-description').textContent=byId[sceneId].description;document.querySelector('[data-action=step]').hidden=!['motion','orbital'].includes(sceneId);if(!isSimulator){history.replaceState({},'',sceneUrl(sceneId));document.querySelector('#scene-page-title').textContent=byId[sceneId].title;}syncURL();closeDialog();toast('Configuration imported. Time reset to zero.');}catch(err){d.querySelector('#import-message').textContent='Import rejected · '+err.message;}};}
 if(action==='share'){const u=new URL(location);u.searchParams.delete('local');if(isSimulator)u.searchParams.set('preset',presets.find(p=>p.sceneId===sceneId)?.id||presets[0].id);if(config){for(const [key,name] of [['dimension','n'],['model','model'],['experiment','experiment'],['projection','projection']])if(config.params[key]!==undefined)u.searchParams.set(name,config.params[key]);}await copyText(u.href);toast('Scene link copied. Export JSON to share every parameter.');}
 if(action==='fullscreen'){const main=document.querySelector('.scene-page');if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.classList.contains('immersive'))document.documentElement.classList.remove('immersive');else {try{await main.requestFullscreen();}catch{document.documentElement.classList.add('immersive');}}host.resize();}
 }catch(err){toast(err.message||String(err));}
});
async function copyText(text){try{await navigator.clipboard.writeText(text);}catch{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok){openDialog('COPY THIS DATA',`<textarea style="width:100%;height:200px">${esc(text)}</textarea>`);}}}
// Re-evaluate direct search links if the shared dictionary loaded after this app.
window.addEventListener('strgo:i18nready',()=>{const field=document.querySelector('#page-search');if(field&&field.value===query){const results=document.querySelector('#page-search-results');if(results)results.innerHTML=resultsMarkup(query);}});
document.addEventListener('input',e=>{if(e.target.id==='search-input'){document.querySelector('#search-results').innerHTML=resultsMarkup(e.target.value);const u=new URL(location);u.searchParams.set('q',e.target.value);history.replaceState({},'',u);}if(e.target.id==='page-search'){const q=e.target.value;document.querySelector('#page-search-results').innerHTML=resultsMarkup(q);const u=new URL(location);u.searchParams.set('q',q);history.replaceState({},'',u);}if(e.target.id==='library-search'){query=e.target.value;renderLibrary();}
 const el=e.target,key=el.dataset.param;if(!key||!config)return;const p=config.params;let value=el.type==='checkbox'?el.checked:el.type==='range'||['dimension','speed'].includes(key)?Number(el.value):el.value;if(typeof value==='number'&&!Number.isFinite(value))return;if(key.startsWith('rotation:')){setPaused(true);p.rotationPlanes[key.split(':')[1]]=value;}else p[key]=value;if(key==='dimension'){const axes='XYZWVU';p.rotationPlanes=Object.fromEntries(Object.entries(p.rotationPlanes).filter(([plane])=>axes.indexOf(plane[1])<p.dimension));}
 const out=document.querySelector(`[data-output="${key}"]`);if(out)out.textContent=typeof value==='number'?value.toFixed(Number(el.step)<.1?2:Number(el.step)<1?1:0):value;
 if('dimension' in p&&p.dimension!==4)p.viewMode='projection';if(p.type==='menger')p.level=Math.min(innerWidth<768?2:3,p.level);if(sceneId==='laws'&&['gravity','curvature','energy','wave','geometry'].includes(key)){host.model.update(host.time,0,false);host.render();}else if(host.model.physics&&['G','epsilon','speed','trails','vectors','acceleration'].includes(key)){Object.assign(host.model.physics.settings,{G:p.G,epsilon:p.epsilon,speed:p.speed});if(['G','epsilon'].includes(key)){setPaused(true);host.model.physics.rebaseline();}host.model.update(host.time,0,false);host.render();}else{host.rebuild(p);fillObjects();}
 if(['dimension','viewMode','type','experiment','preset'].includes(key)){document.querySelector('#parameters').innerHTML=panel(sceneId,p);fillObjects();}if(key==='lockCamera'&&host.controls)host.controls.enabled=!value;const stepButton=document.querySelector('[data-action=step]');if(stepButton)stepButton.hidden=!['motion','orbital'].includes(sceneId)||p.preset==='analytic';syncURL();});
document.addEventListener('change',e=>{if(e.target.id==='object-select'&&e.target.value){const [type,index]=e.target.value.split(':');host.select({type,index:Number(index)});}if(e.target.id==='base-grid'){config.layers.geometry=e.target.checked;host.applyLayers(config.layers);host.render();}if(e.target.id==='quality'){config.quality=e.target.value;host.setQuality(e.target.value);toast('Rendering quality: '+e.target.value);}
 if(e.target.dataset.body){let value=Number(e.target.value);if(e.target.value===''||!Number.isFinite(value)){toast('Enter a finite value.');return;}value=Math.max(Number(e.target.min),Math.min(Number(e.target.max),value));e.target.value=value;setPaused(true);host.model.edit(e.target.dataset.body,value);host.model.update(host.time,0,false);host.render();showSelection(host.model.selection());updateStats(host.model.stats());}
});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();location.href=url('search/?q='+encodeURIComponent(e.target.querySelector('input').value));}if(e.target.id==='page-search-form')e.preventDefault();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const menu=document.querySelector('.mobile-menu');if(menu&&!menu.hidden){menu.hidden=true;document.querySelector('.menu-toggle').focus();document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}if(document.documentElement.classList.contains('immersive')){document.documentElement.classList.remove('immersive');host?.resize();}}
 if(e.target.id==='search-input'){const links=[...document.querySelectorAll('#search-results .search-result')];let i=links.findIndex(l=>l.classList.contains('selected'));if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();i=(i+(e.key==='ArrowDown'?1:links.length-1))%links.length;links.forEach((l,k)=>l.classList.toggle('selected',k===i));links[i]?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&links[i]){e.preventDefault();location.href=links[i].href;}}
});
const s=scenes.find(s=>s.path.replace(/\/$/,'')===route);if(!route)home();else if(s)scenePage(s.id);else if(route==='simulator')scenePage('dimensions',true);else if(route==='library')library();else if(route==='about')about();else if(route==='docs')docs();else if(route==='search')searchPage();else notFound();
setPaused(paused);if(matchMedia('(prefers-reduced-motion: reduce)').matches)document.documentElement.classList.add('motion-reduced');
addEventListener('pagehide',()=>{host?.dispose();if(intro)clearInterval(intro.timer);exitWalk();});
window.polyverse={get host(){return host;},get config(){return config;},get paused(){return paused;},setPaused,changePreset,validateConfig,diagnostics:()=>({scene:host?.id,mode:host?.renderer?'webgl':'static',renderers:document.querySelectorAll('canvas').length,drawCalls:host?.renderer?.info.render.calls,triangles:host?.renderer?.info.render.triangles,geometries:host?.renderer?.info.memory.geometries,time:host?.time,physicsTime:host?.model.physics?.time,quality:host?.quality}),ready:true};
if(!route&&new URLSearchParams(location.search).get('intro')==='1')startIntro();else if(route!=='search'&&new URLSearchParams(location.search).has('q'))openSearch();
if(location.hash)setTimeout(()=>document.querySelector(location.hash)?.scrollIntoView(),150);
